import{_ as t,o as a,c as o,a3 as d}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Departments — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Departments — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/departments"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Departments — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/departments"}]]},"headers":[],"relativePath":"developer-guide/departments.md","filePath":"developer-guide/departments.md","lastUpdated":1787835227000}'),r={name:"developer-guide/departments.md"};function n(s,e,i,c,p,l){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="departments-—-developer-guide" tabindex="-1">Departments — Developer Guide <a class="header-anchor" href="#departments-—-developer-guide" aria-label="Permalink to &quot;Departments — Developer Guide&quot;">​</a></h1><p>Phase 7 HR module. Slug <code>departments</code>, middleware <code>module:departments</code>, permissions <code>departments.*</code>.</p><h2 id="domain" tabindex="-1">Domain <a class="header-anchor" href="#domain" aria-label="Permalink to &quot;Domain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model / table</th><th>Notes</th></tr></thead><tbody><tr><td><code>Department</code> / <code>departments</code></td><td>Soft deletes; UUID; unique <code>(tenant_id, slug)</code>; <code>manager_id</code> → users</td></tr><tr><td><code>department_user</code></td><td>User membership pivot (+ <code>tenant_id</code>)</td></tr><tr><td><code>department_employee</code></td><td>Employee membership pivot (+ <code>tenant_id</code>)</td></tr></tbody></table><p>Enum: <code>DepartmentStatusEnum</code> (<code>active</code> | <code>inactive</code>).</p><p>Service: <code>DepartmentService</code> (CRUD, membership sync, manager assign, performance aggregates). Events → <code>DepartmentEventSubscriber</code> → <code>PlatformAuditService</code> + Spatie <code>LogsActivity</code> (log name <code>departments</code>).</p><p><strong>Visibility (policy + query):</strong></p><ul><li><code>superadmin</code> / <code>admin</code> — org-wide</li><li>Department manager (<code>manager_id</code>) — managed departments + performance</li><li>Others with <code>departments.view</code> — memberships only</li></ul><p><strong>Performance eligibility:</strong> union of attached user IDs, linked employee <code>user_id</code>s, and <code>manager_id</code>. Unlinked employees appear on the roster with <code>performance_eligible: false</code>.</p><p><strong>Manager/member pickers:</strong> <code>GET /users</code> excludes the authenticated user (Users admin list). The Departments form merges the signed-in user into picker options so a solo owner can assign themselves.</p><p><strong>Authz hardening:</strong> <code>manager_id</code> on create/update and <code>PUT …/manager</code> require org-wide <code>assign_manager</code> (admin/superadmin). Membership arrays on create/update require <code>manage_members</code>. Exists rules for managers/members/<code>department_ids</code> are tenant-scoped (<code>tenant_id</code> + not soft-deleted).</p><p>Employee create/update accepts <code>department_ids[]</code> when the Departments module is installed; syncs the pivot and sets legacy <code>employees.department</code> to the primary department name.</p><h2 id="backend-layout" tabindex="-1">Backend layout <a class="header-anchor" href="#backend-layout" aria-label="Permalink to &quot;Backend layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Path</th></tr></thead><tbody><tr><td>Model</td><td><code>app/Models/Department.php</code></td></tr><tr><td>Service</td><td><code>app/Services/Tenant/DepartmentService.php</code></td></tr><tr><td>Controller</td><td><code>app/Http/Controllers/Tenant/Api/V1/DepartmentController.php</code></td></tr><tr><td>Requests</td><td><code>app/Http/Requests/Tenant/Api/V1/Department/*</code></td></tr><tr><td>Policy</td><td><code>app/Policies/DepartmentPolicy.php</code></td></tr><tr><td>Tests</td><td><code>tests/Feature/Tenant/Department/</code></td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>departments.view | create | update | delete | restore | force.delete</span></span>
<span class="line"><span>departments.manage_members | assign_manager | view_performance</span></span></code></pre></div><p>Default role map: admin (all), manager (view/create/update/manage_members/assign_manager/view_performance), staff (view).</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p>See <a href="/api/tenant-v1-departments">tenant-v1-departments.md</a> and <a href="/api/tenant-v1-reports">tenant-v1-reports.md</a> (<code>GET /reports/department-performance</code>).</p><h2 id="reports-digest" tabindex="-1">Reports &amp; digest <a class="header-anchor" href="#reports-digest" aria-label="Permalink to &quot;Reports &amp; digest&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Path</th></tr></thead><tbody><tr><td>Report service</td><td><code>app/Services/Tenant/DepartmentPerformanceReportService.php</code></td></tr><tr><td>Controller</td><td><code>app/Http/Controllers/Tenant/Api/V1/DepartmentPerformanceReportController.php</code></td></tr><tr><td>Request</td><td><code>app/Http/Requests/Tenant/Api/V1/Report/DepartmentPerformanceReportRequest.php</code></td></tr><tr><td>Notification</td><td><code>app/Notifications/Tenant/Report/DepartmentPerformanceDigestNotification.php</code></td></tr><tr><td>Command</td><td><code>app/Console/Commands/SendDepartmentPerformanceDigestCommand.php</code> (<code>reports:send-department-digest</code>)</td></tr><tr><td>Tests</td><td><code>tests/Feature/Tenant/Report/</code>, <code>tests/Feature/Tenant/Notification/DepartmentPerformanceDigestNotificationTest.php</code></td></tr></tbody></table><p>Auth: <code>dashboard.view</code> middleware + owner or <code>User::isDepartmentManager()</code> in the Form Request (no new Spatie permission). Period filter applies to <code>created_at</code> on leads/tasks assigned to <code>Department::performanceUserIds()</code>.</p><p>Digest delivery tracking reuses <code>DailySummaryDelivery</code> with <code>kind = department_weekly</code>; mail send/fail tracked by <code>TrackDailySummaryDelivery</code>.</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><ul><li>Page: <code>src/pages/departments/</code> (list, dedicated create/edit form pages, record view with Details / Users / Employees / Performance sections)</li><li>Reports page: <code>src/pages/reports/department-reports-page.tsx</code> at <code>/reports/departments</code></li><li>Service / keys / permissions: <code>departmentService</code>, <code>departmentReportService</code>, <code>QUERY_KEYS.departments*</code>, <code>QUERY_KEYS.departmentPerformanceReport</code>, <code>PERMISSIONS.dashboard.view</code> + owner/manager gate</li><li>Nav group <strong>HR</strong>, dual-gated <code>module: departments</code> + owner/manager (<code>requiresDepartmentReportAccess</code>)</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Feature/Tenant/Department</span></span></code></pre></div><h2 id="non-goals-v1" tabindex="-1">Non-goals (v1) <a class="header-anchor" href="#non-goals-v1" aria-label="Permalink to &quot;Non-goals (v1)&quot;">​</a></h2><ul><li>Expanding Lead/Task list assignee scoping for department managers</li><li>Hard catalog dependency between <code>departments</code> and <code>employees</code></li><li>Dropping the free-text <code>employees.department</code> column</li></ul>`,29)])])}const g=t(r,[["render",n]]);export{h as __pageData,g as default};
